// src/lib/newsletter/dienst.js – Newsletter je Land: Anmelden → Double-Opt-in → Abmelden (Welle 3, Paket NL). Nur Server.
//
//  1. anmelden: aktiv? (sonst 503 ohne Daten anzunehmen) → E-Mail, Land, Themen prüfen (keine Vorauswahl; mindestens
//     ein Thema) → Protokoll „einwilligung“ (Hash des gezeigten Wortlauts inkl. Land und Themen) → Abo mit Token-Hash
//     + Bestätigungs-Mail (Demo-Postausgang). Antwort immer gleich – keine Auskunft, ob die Adresse schon angemeldet ist.
//  2. bestaetigen (POST vom Knopf der Seite /newsletter/abo/[token], nie per GET): Protokoll „doi“ → Abo aktiv →
//     Willkommens-Mail mit Abmeldelink (List-Unsubscribe + List-Unsubscribe-Post nach RFC 8058).
//  3. abmelden (ein Klick, auch RFC 8058 aus dem Mailprogramm): Protokoll „widerruf“, Abo und Personenzeile weg.
//  4. lesen: Zustand und Themen für die Seite – nie Personendaten.
//
// Ein Token je Abo: vor der Bestätigung öffnet der Link die Bestätigung, danach dieselbe Adresse die Verwaltung mit
// der Abmeldung. Gespeichert wird nur der SHA-256 (src/lib/bericht/token.js). Abhängigkeiten injizierbar (Tests).

import { PlattformFehler } from "@/lib/plattform/fehler";
import * as v from "@/lib/plattform/validierung";
import { newsletterBackend } from "@/lib/plattform/backend/newsletter";
import { herkunftBereinigen } from "@/lib/gruppe/kanal";
import { sha256 } from "@/lib/bericht/anforderung";
import { tokenErzeugen, tokenHash } from "@/lib/bericht/token";
import { newsletterAktiv } from "./versand";
import { newsletterLand, newsletterSprache, themenNormal } from "./themen";
import { ABMELDUNG_TEXT_ID, ANMELDUNG_TEXT_ID, ANTWORT, DOI, DOI_STUNDEN, NEWSLETTER_TEXT_VERSION, bestaetigungsMail, einwilligungsText, willkommensMail } from "./texte";

/** Erlaubte Quellen (wo der Baustein steht) – nur für die Auswertung, nie Personendaten */
export const QUELLEN = Object.freeze(["newsletter", "marktdaten", "footer", "ratgeber", "newsroom", "sonstige"]);

const objekt = (x) => (x && typeof x === "object" && !Array.isArray(x) ? x : {});
const basis = (url) => String(url || "").replace(/\/$/, "");

const standard = (d = {}) => ({
  nl: d.nl || newsletterBackend(),
  aktiv: d.aktiv || (() => newsletterAktiv()),
  jetzt: d.jetzt || (() => new Date()),
});

/** Eingaben prüfen → { email, land, sprache, themen, quelle } oder 422 (ohne den Wert zu nennen) */
export function anmeldungPruefen(roh) {
  const b = objekt(roh);
  const sprache = newsletterSprache(b.sprache);
  const en = sprache === "en";
  const email = v.email(b.email);
  if (!email) throw new PlattformFehler(422, en ? "Please enter a valid e-mail address." : "Bitte geben Sie eine gültige E-Mail-Adresse an.", "email");
  const land = newsletterLand(b.land);
  if (!land) throw new PlattformFehler(422, en ? "Please choose your country." : "Bitte wählen Sie Ihr Land.", "land");
  const themen = themenNormal(b.themen);
  if (!themen.length) throw new PlattformFehler(422, en ? "Please choose at least one topic." : "Bitte wählen Sie mindestens ein Thema.", "themen");
  const quelle = QUELLEN.includes(b.quelle) ? b.quelle : "sonstige";
  return { email, land, sprache, themen, quelle };
}

/** POST /api/newsletter */
export async function anmelden({ body, basisUrl }, deps) {
  const b = objekt(body);
  const sprache = newsletterSprache(b.sprache);
  const antwort = { ok: true, hinweis: ANTWORT[sprache].angefordert };
  if (b.website) return antwort; // Honeypot: still verwerfen
  const d = standard(deps);
  if (!d.aktiv()) throw new PlattformFehler(503, ANTWORT[sprache].aus, "newsletter_aus");
  const e = anmeldungPruefen(b);
  const am = d.jetzt();
  const { token, hash } = tokenErzeugen();
  const { kanal } = herkunftBereinigen(objekt(b.herkunft));
  await d.nl.newsletterAnlegen({
    tokenHash: hash,
    email: e.email,
    land: e.land,
    sprache: e.sprache,
    themen: e.themen,
    quelle: e.quelle,
    kanal,
    ablauf: new Date(am.getTime() + DOI_STUNDEN * 3600e3).toISOString(),
    protokoll: { textId: ANMELDUNG_TEXT_ID, textVersion: NEWSLETTER_TEXT_VERSION, textHash: sha256(einwilligungsText(e)) },
    mail: bestaetigungsMail({ link: `${basis(basisUrl)}/newsletter/abo/${token}`, sprache: e.sprache, land: e.land }),
  });
  return antwort;
}

/** POST /api/newsletter/bestaetigen { token } */
export async function bestaetigen({ token, basisUrl }, deps) {
  const hash = tokenHash(token);
  if (!hash) throw new PlattformFehler(404, "Dieser Link ist ungültig.", "nicht_gefunden");
  const d = standard(deps);
  const r = await d.nl.newsletterBestaetigen({
    tokenHash: hash,
    jetztMs: d.jetzt().getTime(),
    // Wortlaut der Bestätigungsseite in der Sprache des Abos (Hash → Protokoll art "doi")
    doi: (sprache) => ({ textId: DOI.textId, textVersion: NEWSLETTER_TEXT_VERSION, textHash: sha256(DOI[sprache === "en" ? "en" : "de"].text) }),
    willkommen: ({ land, sprache, themen }) =>
      willkommensMail({ link: `${basis(basisUrl)}/newsletter/abo/${token}`, abmeldeUrl: `${basis(basisUrl)}/api/newsletter/abmelden?token=${token}`, sprache, land, themen }),
  });
  if (!r || r.zustand === null) throw new PlattformFehler(404, "Dieser Link ist ungültig.", "nicht_gefunden");
  if (r.zustand === "abgelaufen") throw new PlattformFehler(410, "Dieser Link ist abgelaufen. Bitte melden Sie sich neu an.", "abgelaufen");
  if (r.zustand !== "aktiv") throw new PlattformFehler(409, "Diese Anmeldung besteht nicht mehr.", "beendet");
  return { ok: true, bereits: !!r.bereits };
}

/** POST /api/newsletter/abmelden { token } bzw. RFC 8058 */
export async function abmelden({ token, kanal = "abmeldelink" }, deps) {
  const hash = tokenHash(token);
  if (!hash) throw new PlattformFehler(404, "Dieser Link ist ungültig.", "nicht_gefunden");
  const d = standard(deps);
  const r = await d.nl.newsletterAbmelden({ tokenHash: hash, kanal, textId: ABMELDUNG_TEXT_ID, textVersion: NEWSLETTER_TEXT_VERSION, jetztMs: d.jetzt().getTime() });
  if (!r || r.zustand === null) throw new PlattformFehler(404, "Dieser Link ist ungültig.", "nicht_gefunden");
  return { ok: true, bereits: !!r.bereits };
}

/** Für die Seite /newsletter/abo/[token]: { zustand, abo? } – nie Personendaten */
export async function lesen({ token }, deps) {
  const hash = tokenHash(token);
  if (!hash) return { zustand: null };
  const d = { nl: deps?.nl || newsletterBackend(), jetzt: deps?.jetzt || (() => new Date()) };
  return d.nl.newsletterLesen({ tokenHash: hash, jetztMs: d.jetzt().getTime() });
}
// src/lib/newsletter/versand.js – Darf der Newsletter Anmeldungen annehmen und Mails erzeugen? (Welle 3, Paket NL)
//
//   newsletterAktiv() === true NUR, wenn das Demo-Backend läuft UND NEXT_PUBLIC_SITE_ENV nicht "production" ist.
//   Im Demo-Modus landen alle Mails im Demo-Postausgang (db.postausgang) – es geht nichts raus.
//   In jedem anderen Fall (Frappe, Produktion) nimmt der Server KEINE Adressen an; der Baustein zeigt ehrlich
//   „Der Newsletter startet mit dem Livegang.“ (keine Datenerhebung ohne Zweck).
//
// TODO Inhaber/B0 + Betrieb: Versanddienst mit AVV (EU), Absendername/-adresse und Versanddomain (SPF, DKIM, DMARC),
//   Frappe-Spiegel (Abo-DocType, DOI, Abmeldung) – erst danach einen echten Produktionsschalter ergänzen.

import { backendName } from "@/lib/plattform/backend";

function aktivesBackend() {
  try {
    return backendName();
  } catch {
    return null;
  }
}

/**
 * @param {{ backend?: string|null, env?: Record<string,string|undefined> }} [o] für Tests injizierbar
 */
export function newsletterAktiv({ backend, env = process.env } = {}) {
  const b = backend === undefined ? aktivesBackend() : backend;
  if (String(env.NEXT_PUBLIC_SITE_ENV || "").trim().toLowerCase() === "production") return false;
  return b === "demo";
}

/** Für GET /api/newsletter: { aktiv, modus } – ohne Interna */
export function newsletterStatus(o = {}) {
  const aktiv = newsletterAktiv(o);
  return { aktiv, modus: aktiv ? "demo" : "aus" };
}
// src/lib/newsletter/zustand.js – Zustand eines Newsletter-Abos (Welle 3, Paket NL). Rein, ohne Abhängigkeiten.
//
//   "offen"       angemeldet, Bestätigung ausstehend (höchstens DOI_STUNDEN)
//   "aktiv"       bestätigt – erhält den Newsletter, bis zur Abmeldung
//   "abgemeldet"  abgemeldet (Grabstein ohne Personendaten)
//   "ersetzt"     durch eine neuere, bestätigte Anmeldung derselben Adresse ersetzt (Grabstein)
//   "abgelaufen"  nicht rechtzeitig bestätigt (Grabstein, Angaben gelöscht)
//   null          unbekannt

export const ABO_ZUSTAENDE = Object.freeze(["offen", "aktiv", "abgemeldet", "ersetzt", "abgelaufen"]);

/** Grabsteine (ohne Personendaten) verschwinden nach so vielen Tagen. */
export const GRABSTEIN_TAGE = 400;

export function aboZustand(abo, jetztMs = Date.now()) {
  if (!abo) return null;
  if (["aktiv", "abgemeldet", "ersetzt", "abgelaufen"].includes(abo.status)) return abo.status;
  const ablauf = Date.parse(abo.ablauf || "");
  if (!Number.isFinite(ablauf) || jetztMs > ablauf) return "abgelaufen";
  return "offen";
}
// src/lib/newsletter/themen.js – Themen und Eingabeprüfung des Newsletters je Land (Welle 3, Paket NL)
//
// Reine Funktionen ohne Server- oder React-Abhängigkeiten: genutzt vom Baustein (Browser), vom Dienst (Server)
// und von den Tests. Relative Importe mit Dateiendung (node:test lädt das Modul ohne Alias).
//
// Regeln (Masterplan Abschnitt 5 und 7, Inhaber):
//  - Themen sind frei wählbar, keines ist vorausgewählt; mindestens eines ist nötig (sonst gäbe es nichts zu senden).
//  - Jedes Abo gehört zu genau EINEM Land (DE, AT, CH): Inhalte, Recht und Zahlen bleiben je Land getrennt.
//  - Das Land kommt aus der Länderwahl der Seite (/de, /at, /ch bzw. gespeicherte Wahl); ohne Wahl wählt man es selbst.

export const NEWSLETTER_LAENDER = Object.freeze(["DE", "AT", "CH"]);
export const NEWSLETTER_SPRACHEN = Object.freeze(["de", "en"]);

/** Themen (ID → Texte). Reihenfolge = Anzeige. */
export const THEMEN = Object.freeze([
  Object.freeze({
    id: "fristen_foerderung",
    de: "Fristen & Förderung",
    en: "Deadlines & funding",
    textDe: "Gebotstermine, Förderaufrufe und Fristen, sobald sie amtlich bekannt sind.",
    textEn: "Bidding dates, funding calls and deadlines as soon as they are officially announced.",
  }),
  Object.freeze({
    id: "marktdaten",
    de: "Marktdaten",
    en: "Market data",
    textDe: "Zuschlagswerte, Marktwerte und Zubau – mit Quelle und Stand.",
    textEn: "Award values, market values and additions – with source and date.",
  }),
  Object.freeze({
    id: "flaechen_pacht",
    de: "Flächen & Pacht",
    en: "Land & leases",
    textDe: "Was sich für Eigentümer und Landwirte bei Pacht, Planung und Genehmigung ändert.",
    textEn: "What changes for landowners and farmers in leases, planning and permits.",
  }),
  Object.freeze({
    id: "energiegemeinschaften",
    de: "Energiegemeinschaften",
    en: "Energy communities",
    textDe: "Regeln, Fristen und Praxis für gemeinsam genutzten Strom.",
    textEn: "Rules, deadlines and practice for shared electricity.",
  }),
]);

export const THEMEN_IDS = Object.freeze(THEMEN.map((t) => t.id));

/** Thema in der Sprache ("de" | "en") → { id, titel, text } */
export function themaIn(t, sprache = "de") {
  const en = sprache === "en";
  return { id: t.id, titel: en ? t.en : t.de, text: en ? t.textEn : t.textDe };
}

/** Themenliste prüfen: nur bekannte IDs, ohne Doppel, in fester Reihenfolge. Unbekanntes wird verworfen. */
export function themenNormal(roh) {
  if (!Array.isArray(roh)) return [];
  const gewaehlt = new Set(roh.filter((x) => typeof x === "string"));
  return THEMEN_IDS.filter((id) => gewaehlt.has(id));
}

/** "at" → "AT"; unbekannt → "" */
export function newsletterLand(wert) {
  const s = typeof wert === "string" ? wert.trim().toUpperCase() : "";
  return NEWSLETTER_LAENDER.includes(s) ? s : "";
}

/** "en" → "en", alles andere → "de" */
export const newsletterSprache = (wert) => (wert === "en" ? "en" : "de");

