116	// src/lib/verifizierung.js – Bestätigungscodes für Google Search Console und Bing Webmaster Tools (Welle 3, Paket NL)
117	//
118	// Die Codes kommen NUR aus Umgebungsvariablen (.env.example): NEXT_PUBLIC_GSC_VERIFICATION, NEXT_PUBLIC_BING_VERIFICATION.
119	// Ohne Wert entsteht kein Meta-Tag. Ein Wert wird nur übernommen, wenn er wie ein Bestätigungscode aussieht
120	// (Buchstaben, Ziffern, „-“ und „_“, 6–100 Zeichen) – versehentlich eingefügte ganze Meta-Tags, Anführungszeichen
121	// oder Leerzeichen erzeugen kein kaputtes oder fremdes Markup. Es wird nichts extern angemeldet: Die Anmeldung der
122	// Domain in Search Console und Bing macht der Inhaber nach dem Domainkauf (dann Wert setzen, neu bauen).
123	// Rein, ohne Importe (node:test).
124	
125	const CODE = /^[A-Za-z0-9_-]{6,100}$/;
126	
127	/** Wert prüfen: gültiger Code oder null */
128	export function verifizierungsCode(wert) {
129	  const s = typeof wert === "string" ? wert.trim() : "";
130	  return CODE.test(s) ? s : null;
131	}
