133	/**
134	 * Next.js-Metadaten `verification` aus den Umgebungswerten – oder {} ohne gültigen Code.
135	 * @param {{ google?: string, bing?: string }} werte  process.env.NEXT_PUBLIC_GSC_VERIFICATION / …_BING_VERIFICATION
136	 */
137	export function verifizierungMetadaten({ google, bing } = {}) {
138	  const g = verifizierungsCode(google);
139	  const b = verifizierungsCode(bing);
140	  if (!g && !b) return {};
141	  return { verification: { ...(g ? { google: g } : {}), ...(b ? { other: { "msvalidate.01": b } } : {}) } };
142	}
